-- Classic 1.60: block value of shields. The Classic client data has no base block value any more (only 2 shields carry an extra
-- block value stat), the vanilla values (VMaNGOS item_template.block, latest patch) are used by Player::GetShieldBlockValue:
-- blocked damage = shield block value + strength / 20 - 1 (vanilla). Safe to run again.
CREATE TABLE IF NOT EXISTS `item_classic_block` (
  `entry` int unsigned NOT NULL,
  `block` int unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`entry`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DELETE FROM `item_classic_block`;
